	["Features/MobDetail.lua"] = [======[
-- MobDetail is the right side of the Mob Dictionary (MobBrowser): the one
-- mob picked, laid out to be read at a glance:
--
--   * Its name, kind, level, how many are alive in this server, its status
--     effect, and a 5-step threat meter.
--   * Health, speed and damage in big numbers, with their rank.
--   * DROPS PER KILL: every item it drops with the chance per kill as the
--     server rolls it, with and without the player's Luck, and the average
--     number of kills for one.
--   * Every number as a bar against the strongest of its kind, its other
--     values as tags, and its status effect.
--   * ADD TO ENEMY PRIORITY and COPY NAME.
return {
    Name = "MobDetail",
    Dependencies = {"Runtime", "Components", "Floating", "DetailKit", "MobDictionary"},

    Start = function(Context)
        local UI = Context.UI
        local AICUI = Context.AICUI
        local AICCombat = Context.AICCombat
        local AICProfile = Context.AICProfile
        local Floating = Context.Floating
        local Kit = Context.DetailKit
        local Dictionary = Context.MobDictionary

        local New, Label, Button, ClearChildren = Floating.New, Floating.Label, Floating.Button, Floating.ClearChildren
        local FormatNumber, FormatPercent, TrimDecimals = Kit.FormatNumber, Kit.FormatPercent, Kit.TrimDecimals
        local Card, Heading, Note, Badge, Strip, Track, BarRow = Kit.Card, Kit.Heading, Kit.Note, Kit.Badge, Kit.Strip, Kit.Track, Kit.BarRow

        local STAT_BAR_HEIGHT = 30
        local DROP_ROW_HEIGHT = 42
        local THREAT_SEGMENTS = 5
        --// The game announces a drop of 1 in this many or rarer as rare.
        local RARE_RARITY = 10

        local HEALTH_COLOR = Kit.GOOD_COLOR
        local EXTREME_COLOR = Color3.fromRGB(255, 60, 60)

        local Detail = {
            Name = "MobDetail",
            HEALTH_COLOR = HEALTH_COLOR,
            THREAT_SEGMENTS = THREAT_SEGMENTS,
            S = {
                Selected = nil,
                --// Luck and known drops the detail was built with; a change
                --// rebuilds it.
                Signature = nil,
                --// Updated in place on every refresh.
                LiveBadge = nil,
                PriorityButton = nil,
            },
        }

        local S = Detail.S
        local Theme, Scroll

        ------------------------------------------------------------------------
        --// Describing
        ------------------------------------------------------------------------

        --// Average kills for one drop.
        local function FormatKills(Chance)
            if Chance <= 0 then
                return "NEVER"
            end

            local Kills = 1 / Chance

            if Kills < 1.05 then
                return "EVERY KILL"
            elseif Kills < 10 then
                return "~" .. TrimDecimals(string.format("%.1f", Kills)) .. " KILLS"
            end

            return "~" .. FormatNumber(math.floor(Kills + 0.5)) .. " KILLS"
        end

        local THREAT_LEVELS = {
            { Name = "LOW", Color = function() return HEALTH_COLOR end },
            { Name = "MODERATE", Color = function() return UI.Theme.Cyan end },
            { Name = "HIGH", Color = function() return UI.Theme.Warning end },
            { Name = "SEVERE", Color = function() return UI.Theme.Danger end },
            { Name = "EXTREME", Color = function() return EXTREME_COLOR end },
        }

        --// Filled segments (1..THREAT_SEGMENTS), level name and colour.
        function Detail.DescribeThreat(Entry)
            local Filled = math.clamp(math.ceil(Dictionary.GetThreat(Entry) * THREAT_SEGMENTS), 1, THREAT_SEGMENTS)
            local Level = THREAT_LEVELS[Filled]
            return Filled, Level.Name, Level.Color()
        end

        function Detail.GetKindColor(Entry)
            return Entry.Kind == "Boss" and UI.Theme.Danger or UI.Theme.Cyan
        end

        function Detail.IsInPriority(Name)
            return AICCombat.IsEntityInPriority ~= nil and AICCombat.IsEntityInPriority(Name)
        end

        local function GetStatColor(Stat)
            if Stat.Key == "Humanoid.MaxHealth" then
                return HEALTH_COLOR
            elseif Stat.Group == "Combat" then
                return Theme.Danger
            elseif Stat.Group == "Rewards" then
                return Theme.Cyan
            end

            return Theme.TextSecondary
        end

        local function DescribeLive(Name)
            local Count = Dictionary:GetLive(Name)

            if Count > 0 then
                return string.format("●  %d IN SERVER", Count), HEALTH_COLOR
            end

            return "○  NOT IN SERVER", Theme.TextMuted
        end

        ------------------------------------------------------------------------
        --// Sections
        ------------------------------------------------------------------------

        local function BuildThreatMeter(Parent, Entry, Order)
            local Filled, LevelName, Color = Detail.DescribeThreat(Entry)
            local Row = Strip(Parent, 16, Order)

            Label(Row, "THREAT", 9, {
                Size = UDim2.fromOffset(52, 16),
                TextColor3 = Theme.TextMuted,
                Font = Floating.Fonts.Bold,
                LayoutOrder = 0,
            })

            for Index = 1, THREAT_SEGMENTS do
                New("Frame", {
                    Parent = Row,
                    Size = UDim2.fromOffset(22, 8),
                    BackgroundColor3 = Index <= Filled and Color or Theme.Background,
                    BorderSizePixel = 0,
                    LayoutOrder = Index,
                })
            end

            Label(Row, "  " .. LevelName, 10, {
                Size = UDim2.fromOffset(90, 16),
                TextColor3 = Color,
                Font = Floating.Fonts.Bold,
                LayoutOrder = THREAT_SEGMENTS + 1,
            })
        end

        local function BuildHero(Entry, Order)
            local Hero = Card(Scroll, Order)

            Label(Hero, string.upper(Entry.Name), 16, {
                Font = Floating.Fonts.Bold,
                TextColor3 = Theme.Text,
                LayoutOrder = 1,
            })

            local Badges = Strip(Hero, 18, 2)
            Badge(Badges, string.upper(Entry.Kind), Detail.GetKindColor(Entry), 1)

            local Level = Dictionary.GetStat(Entry, "Config.LVL")

            if type(Level) == "number" then
                Badge(Badges, "LV " .. FormatNumber(Level), Theme.TextSecondary, 2)
            end

            local LiveText, LiveColor = DescribeLive(Entry.Name)
            S.LiveBadge = Badge(Badges, LiveText, LiveColor, 3)

            if Entry.Status then
                Badge(Badges, "☠  " .. string.upper(Entry.Status.Name), Theme.Warning, 4)
            end

            BuildThreatMeter(Hero, Entry, 3)
        end

        --// Health, speed and the first combat number in big type.
        local function BuildTiles(Entry, Order)
            local Picked = {}

            for _, Key in ipairs({ "Humanoid.MaxHealth", "Humanoid.WalkSpeed" }) do
                for _, Stat in ipairs(Entry.Stats) do
                    if Stat.Key == Key then
                        table.insert(Picked, Stat)
                    end
                end
            end

            for _, Stat in ipairs(Entry.Stats) do
                if Stat.Numeric and Stat.Group == "Combat" then
                    table.insert(Picked, Stat)
                    break
                end
            end

            local Tiles = {}

            for _, Stat in ipairs(Picked) do
                local _, Rank, Total = Dictionary.GetScale(Stat, Entry.Kind)

                table.insert(Tiles, {
                    Value = FormatNumber(Stat.Value),
                    Label = Stat.Label,
                    Note = Rank and string.format("#%d OF %d", Rank, Total) or nil,
                    Color = GetStatColor(Stat),
                })
            end

            Kit.Tiles(Scroll, Order, Tiles)
        end

        --// One item: the chance per kill with Luck (bright) over the chance
        --// without it (grey), and how it is rolled.
        local function BuildDropRow(Parent, Drop, LuckPercent, Order)
            local Chance, Expected = Dictionary.GetDropOdds(Drop, LuckPercent)
            local BaseChance = Dictionary.GetDropOdds(Drop, 0)
            local Holder = BarRow(
                Parent, DROP_ROW_HEIGHT, Order,
                string.upper(Drop.Name),
                FormatPercent(Chance) .. "   " .. FormatKills(Chance),
                Chance > 0 and Theme.Cyan or Theme.Danger
            )

            local Bars = { { Fraction = Chance, Color = Theme.Cyan } }

            if LuckPercent > 0 then
                table.insert(Bars, { Fraction = BaseChance, Color = Theme.TextSecondary })
            end

            Track(Holder, 18, Bars)

            local Parts = {
                "1 IN " .. FormatNumber(Drop.Rarity),
                FormatNumber(Drop.Rounds) .. (Drop.Rounds == 1 and " ROLL" or " ROLLS"),
                "~" .. TrimDecimals(string.format("%.2f", Expected)) .. " PER KILL",
            }

            if LuckPercent > 0 then
                table.insert(Parts, "NO LUCK " .. FormatPercent(BaseChance))
            end

            if Drop.Rarity >= RARE_RARITY then
                table.insert(Parts, "RARE")
            end

            Label(Holder, table.concat(Parts, "  ·  "), 8, {
                Position = UDim2.fromOffset(0, 27),
                Size = UDim2.new(1, 0, 0, 12),
                TextColor3 = Theme.TextMuted,
            })
        end

        local function BuildDrops(Entry, Order)
            local DropCard = Card(Scroll, Order)
            local Luck, Cap, LuckPercent = Dictionary.GetLuck()

            Heading(DropCard, "DROPS PER KILL", 0)

            Label(DropCard, string.format(
                "LUCK %s / %s   →   +%s%% ON EVERY ROLL",
                FormatNumber(Luck), FormatNumber(Cap), FormatNumber(LuckPercent)
            ), 10, {
                TextColor3 = LuckPercent > 0 and Theme.Cyan or Theme.TextMuted,
                Font = Floating.Fonts.Bold,
                LayoutOrder = 1,
            })

            local Drops = Dictionary:GetDrops(Entry.Name)

            if not Drops then
                Note(DropCard, "Drops are read from a live one: they show once this mob has been in the server, and are saved for later runs.", 2)
                return
            elseif #Drops == 0 then
                Note(DropCard, "Drops nothing.", 2)
                return
            end

            for Index, Drop in ipairs(Drops) do
                BuildDropRow(DropCard, Drop, LuckPercent, Index + 1)
            end

            Note(DropCard, "Bright bar = with your Luck, grey = without. Event items are not counted.", #Drops + 2)
        end

        local GROUP_ORDER = { "Core", "Combat", "Rewards", "Other" }
        local GROUP_TITLES = { Core = "BODY", Combat = "COMBAT", Rewards = "REWARDS", Other = "OTHER" }

        --// Every number as a bar against the strongest of its kind, by group.
        local function BuildBars(Entry, Order)
            local BarsCard = nil

            for _, Group in ipairs(GROUP_ORDER) do
                local Stats = {}

                for _, Stat in ipairs(Entry.Stats) do
                    if Stat.Numeric and Stat.Group == Group then
                        table.insert(Stats, Stat)
                    end
                end

                if #Stats > 0 then
                    if not BarsCard then
                        BarsCard = Card(Scroll, Order)
                        Heading(BarsCard, "COMPARED TO THE STRONGEST " .. string.upper(Entry.Kind), 0)
                    end

                    local GroupOrder = #BarsCard:GetChildren() * 100
                    Heading(BarsCard, GROUP_TITLES[Group], GroupOrder).TextColor3 = Theme.TextSecondary

                    for Index, Stat in ipairs(Stats) do
                        local Fraction, Rank, Total = Dictionary.GetScale(Stat, Entry.Kind)
                        local Value = FormatNumber(Stat.Value) .. (Rank and string.format("   #%d/%d", Rank, Total) or "")
                        local Holder = BarRow(BarsCard, STAT_BAR_HEIGHT, GroupOrder + Index, Stat.Label, Value)
                        Track(Holder, 18, { { Fraction = Fraction, Color = GetStatColor(Stat) } })
                    end
                end
            end
        end

        --// Values that are not numbers, and the status effect.
        local function BuildTraits(Entry, Order)
            local Traits = {}

            for _, Stat in ipairs(Entry.Stats) do
                if not Stat.Numeric then
                    table.insert(Traits, Stat)
                end
            end

            if #Traits > 0 then
                local TraitsCard = Card(Scroll, Order)
                Heading(TraitsCard, "TRAITS", 0)
                Kit.Tags(TraitsCard, Traits, Theme.TextSecondary, 1)
            end

            if Entry.Status then
                local StatusCard = Card(Scroll, Order + 1)
                Heading(StatusCard, "STATUS EFFECT", 0)

                Label(StatusCard, "☠  " .. string.upper(Entry.Status.Name), 13, {
                    TextColor3 = Theme.Warning,
                    Font = Floating.Fonts.Bold,
                    LayoutOrder = 1,
                })

                if #Entry.Status.Props > 0 then
                    Kit.Tags(StatusCard, Entry.Status.Props, Theme.Warning, 2)
                end
            end
        end

        local function UpdatePriorityButton()
            local PriorityButton = S.PriorityButton

            if not PriorityButton or not S.Selected then
                return
            end

            local Added = Detail.IsInPriority(S.Selected)
            PriorityButton.Text = Added and "✓  IN ENEMY PRIORITY" or "+  ADD TO ENEMY PRIORITY"
            PriorityButton.TextColor3 = Added and HEALTH_COLOR or Theme.Cyan
        end

        local function BuildActions(Entry, Order)
            local Row = Strip(Scroll, 28, Order)
            Row.Size = UDim2.new(1, -6, 0, 28)

            S.PriorityButton = Button(Row, "", Theme.Cyan, {
                Size = UDim2.new(0.62, -2, 1, 0),
                LayoutOrder = 1,
            })

            local CopyButton = Button(Row, "COPY NAME", Theme.TextMuted, {
                Size = UDim2.new(0.38, -2, 1, 0),
                LayoutOrder = 2,
            })

            S.PriorityButton.Activated:Connect(function()
                if Detail.IsInPriority(Entry.Name) then
                    return
                end

                if not AICProfile.S.ActiveProfileName then
                    Context.NotifyAction("Enemy Priority", "Load or create a profile first")
                    return
                end

                if AICUI.S.AddPriorityTarget then
                    AICUI.S.AddPriorityTarget(Entry.Name)
                end

                UpdatePriorityButton()
            end)

            CopyButton.Activated:Connect(function()
                local Copied = Floating.CopyText(Entry.Name)
                Context.NotifyAction("Mob Dictionary", Copied and "Name copied" or "No clipboard here")
            end)

            UpdatePriorityButton()
        end

        --// Changes when the Luck bonus changes or the drops or AwardParam
        --// become known.
        local function GetSignature()
            local _, _, LuckPercent = Dictionary.GetLuck()
            local Drops = S.Selected and Dictionary:GetDrops(S.Selected)
            local AwardParam = S.Selected and Dictionary:GetAwardParam(S.Selected)
            return tostring(LuckPercent) .. "|" .. (Drops and #Drops or "?") .. "|" .. tostring(AwardParam)
        end

        ------------------------------------------------------------------------
        --// API
        ------------------------------------------------------------------------

        function Detail:Build(Parent)
            Theme = UI.Theme
            Scroll = Parent
        end

        function Detail:GetSelected()
            return S.Selected
        end

        function Detail:Rebuild()
            if not Scroll then
                return
            end

            ClearChildren(Scroll)
            S.LiveBadge = nil
            S.PriorityButton = nil
            S.Signature = GetSignature()

            local Entry = S.Selected and Dictionary:Get(S.Selected)

            if not Entry then
                local Message = "Pick a mob on the left"

                if Dictionary.S.Loading then
                    Message = "Loading the mob dictionary..."
                elseif Dictionary.S.Error then
                    Message = Dictionary.S.Error
                end

                Note(Scroll, Message, 0, Dictionary.S.Error and Theme.Danger or nil)
                return
            end

            BuildHero(Entry, 1)
            BuildTiles(Entry, 2)
            BuildDrops(Entry, 3)
            BuildBars(Entry, 4)
            BuildTraits(Entry, 5)
            BuildActions(Entry, 7)
        end

        function Detail:Select(Name)
            S.Selected = Name
            Detail:Rebuild()
        end

        --// Live count and priority mark in place; the whole detail again when
        --// Luck changed or the drops just became known.
        function Detail:Refresh()
            if not Scroll then
                return
            end

            if GetSignature() ~= S.Signature then
                Detail:Rebuild()
                return
            end

            if S.LiveBadge and S.Selected then
                Kit.SetBadge(S.LiveBadge, DescribeLive(S.Selected))
            end

            UpdatePriorityButton()
        end

        return Detail
    end,
}
]======],
	["Features/MobDictionary.lua"] = [======[
-- MobDictionary reads the game's mob dictionary (ReplicatedStorage.BuildAssets
-- invoked with "MobDict": every model in ServerStorage Mobs and Bosses, with
-- its Value children, its Configuration values and its Humanoid's MaxHealth
-- and WalkSpeed) and turns it into one entry per mob for the Mob Dictionary
-- window (MobBrowser):
--
--   Entry = {
--       Name, Kind ("Mob" / "Boss"),
--       Stats = { { Key, Label, Value, Group, Numeric } ... },
--       Status = { Name, Props = { { Label, Value } ... } } or nil,
--   }
--
-- Numeric stats are also ranked against the other mobs of the same kind
-- (GetScale), so the window can show each one as a share of the strongest's,
-- and GetThreat rates a mob by where its health and damage rank among all.
--
-- Drops are not in the dictionary: they are read from the first live one of
-- each mob (Config.MaxDrops), and GetDropOdds works out the chance per kill
-- the way the server's AwardPlayer rolls it, with the player's Luck. Drops
-- read are saved to DROPS_FILE, so they are known in later runs before the
-- mob is seen again; the file is written only when a mob is not saved yet
-- or its live drops differ from the saved ones.
--
-- A mob whose Config.AwardType is "HealthPercent" only rewards a player who
-- dealt at least AwardParam percent of its health (an attribute on AwardType,
-- which the dictionary leaves out). It is read from a live one too, saved in
-- DROPS_FILE beside the drops, and shown as the AWARD_PARAM_KEY stat.
return {
    Name = "MobDictionary",
    Dependencies = {"Runtime", "ProfileManager"},

    Start = function(Context)
        local Replicated = Context.Services.Replicated
        local HttpService = Context.Services.HttpService
        local AICProfile = Context.AICProfile

        local REMOTE_NAME = "BuildAssets"
        local REMOTE_ARGUMENT = "MobDict"
        --// The server's folder names, and what each is shown as.
        local KIND_BY_FOLDER = { Mobs = "Mob", Bosses = "Boss" }
        --// Values already shown elsewhere (the mob's name, its drops).
        local HIDDEN_KEYS = { Entity = true, MaxDrops = true }
        --// Groups for names the words below would miss or misplace.
        local EXACT_GROUPS = { Col = "Rewards", LVL = "Core" }
        --// A stat whose name holds one of these words is grouped under it.
        --// Checked in order; the first match wins.
        local GROUP_WORDS = {
            { Group = "Rewards", Words = { "xp", "exp", "gold", "coin", "money", "cash", "drop", "loot", "reward", "chance" } },
            { Group = "Combat", Words = { "damage", "dmg", "attack", "atk", "range", "aggro", "cooldown", "crit", "defense", "armor", "hit", "power", "strength" } },
        }
        --// Stats that make a mob dangerous, for the threat meter.
        local THREAT_WORDS = { "damage", "dmg", "attack", "atk", "power", "strength" }
        --// Luck adds Luck / LUCK_DIVISOR percent to every drop roll, Luck
        --// capped at CoreCommons.PHYSICAL_STAT_MAX (this when unreadable).
        local LUCK_DIVISOR = 100
        local DEFAULT_LUCK_CAP = 500
        --// Odds like 100 / 3 * 3 land a hair under the integer.
        local ROUNDING_EPSILON = 1e-9
        --// Guard against a broken roll count.
        local MAX_ROUNDS = 1000
        --// A StatusEffect holding one of these means no effect.
        local NO_STATUS = { none = true, ["nil"] = true, ["0"] = true }
        --// Seconds before a server that never answers counts as failed, so
        --// RELOAD can ask again.
        local LOAD_TIMEOUT = 20
        --// Saved drops, shared by every profile and PlaceId.
        local DROPS_FILE = Context.PROFILE_FOLDER .. "/MobDrops.json"
        local DROPS_FILE_VERSION = 1
        --// Name:Rarity:Rounds, numbers to 10 significant digits.
        local DROPS_SIGNATURE_FORMAT = "%s:%.10g:%.10g"
        --// Seconds between background scans of workspace.Mobs for drops.
        local LIVE_SCAN_INTERVAL = 5
        --// Config.AwardType value whose AwardParam attribute is the share of
        --// the mob's health (percent) a player must deal to be rewarded.
        local AWARD_TYPE_HEALTH_PERCENT = "HealthPercent"
        local AWARD_PARAM_ATTRIBUTE = "AwardParam"
        local AWARD_PARAM_KEY = "Config.AwardParam"
        --// No THREAT_WORDS in it, so it does not count toward the threat meter.
        local AWARD_PARAM_LABEL = "AWARD MIN HEALTH %"

        local Dictionary = {
            Name = "MobDictionary",
            KIND_BY_FOLDER = KIND_BY_FOLDER,
            S = {
                Entries = {},
                ByName = {},
                --// Stat key -> { Max, Sorted (descending values) }, over
                --// every mob; KindScales[Kind] is the same per kind.
                Scales = {},
                KindScales = {},
                Loading = false,
                Loaded = false,
                Error = nil,
                --// Called after every load, whether it worked or not.
                OnLoaded = nil,
                --// Entity name -> mobs alive in workspace.Mobs.
                Live = {},
                --// Entity name -> drops read from a live one (ReadDrops) or
                --// loaded from DROPS_FILE.
                Drops = {},
                --// Entity name -> AwardParam (percent of health to deal to
                --// be rewarded), read from a live one or DROPS_FILE.
                AwardParams = {},
                --// Entity name -> DropsSignature of what DROPS_FILE holds.
                SavedSignatures = {},
                --// Entity names whose live drops were read this run; each is
                --// read once (to catch a game update), then trusted.
                CheckedLive = {},
                --// A recorded change is not in DROPS_FILE yet (the write
                --// failed); tried again on every scan.
                SavePending = false,
                LuckCap = nil,
                LuckCapRequested = false,
                --// Bumped by every load; a stale or timed-out answer is dropped.
                LoadToken = 0,
            },
        }

        local S = Dictionary.S

        local function HasWord(Text, Words)
            local Lower = string.lower(Text)

            for _, Word in ipairs(Words) do
                if string.find(Lower, Word, 1, true) then
                    return true
                end
            end

            return false
        end

        local function GetGroup(Name)
            if EXACT_GROUPS[Name] then
                return EXACT_GROUPS[Name]
            end

            for _, Rule in ipairs(GROUP_WORDS) do
                if HasWord(Name, Rule.Words) then
                    return Rule.Group
                end
            end

            return "Other"
        end

        function Dictionary.IsThreatStat(Stat)
            return Stat.Key == "Humanoid.MaxHealth" or HasWord(Stat.Label, THREAT_WORDS)
        end

        --// "AttackRange" -> "ATTACK RANGE".
        function Dictionary.Prettify(Name)
            local Spaced = string.gsub(Name, "(%l)(%u)", "%1 %2")
            Spaced = string.gsub(Spaced, "_", " ")
            return string.upper(Spaced)
        end

        --// The server sends each value as { Value = x }; anything else is
        --// passed through as it is.
        local function Unwrap(Raw)
            if type(Raw) == "table" then
                return Raw.Value
            end

            return Raw
        end

        local function AddStat(Stats, Key, Name, Value, Group)
            if Value == nil or HIDDEN_KEYS[Name] then
                return
            end

            table.insert(Stats, {
                Key = Key,
                Label = Dictionary.Prettify(Name),
                Value = Value,
                Group = Group or GetGroup(Name),
                Numeric = type(Value) == "number",
            })
        end

        local function ReadStatus(Raw)
            if type(Raw) ~= "table" then
                return nil
            end

            --// Most mobs carry an empty StatusEffect: they have none.
            local Effect = Raw.Value

            if Effect == nil or Effect == false or Effect == "" or NO_STATUS[string.lower(tostring(Effect))] then
                return nil
            end

            local Status = { Name = tostring(Effect), Props = {} }

            for Name, Child in pairs(Raw) do
                if Name ~= "Value" then
                    table.insert(Status.Props, { Label = Dictionary.Prettify(Name), Value = Unwrap(Child) })
                end
            end

            table.sort(Status.Props, function(A, B)
                return A.Label < B.Label
            end)

            return Status
        end

        local function ReadEntry(Name, Raw)
            local Entry = {
                Name = Name,
                Kind = KIND_BY_FOLDER[Raw.Value] or tostring(Raw.Value or "Mob"),
                Stats = {},
                Status = nil,
            }

            local Humanoid = Raw.Humanoid

            if type(Humanoid) == "table" then
                AddStat(Entry.Stats, "Humanoid.MaxHealth", "Health", tonumber(Humanoid.MaxHealth), "Core")
                AddStat(Entry.Stats, "Humanoid.WalkSpeed", "WalkSpeed", tonumber(Humanoid.WalkSpeed), "Core")
            end

            for Key, Child in pairs(Raw) do
                if Key == "Config" and type(Child) == "table" then
                    for ConfigKey, ConfigChild in pairs(Child) do
                        if ConfigKey == "StatusEffect" then
                            Entry.Status = ReadStatus(ConfigChild)
                        else
                            AddStat(Entry.Stats, "Config." .. ConfigKey, ConfigKey, Unwrap(ConfigChild))
                        end
                    end
                elseif Key ~= "Value" and Key ~= "Humanoid" then
                    AddStat(Entry.Stats, "Value." .. Key, Key, Unwrap(Child))
                end
            end

            --// Health and speed first, then by name.
            table.sort(Entry.Stats, function(A, B)
                if (A.Group == "Core") ~= (B.Group == "Core") then
                    return A.Group == "Core"
                end

                return A.Label < B.Label
            end)

            return Entry
        end

        function Dictionary.GetStat(Entry, Key)
            for _, Stat in ipairs(Entry.Stats) do
                if Stat.Key == Key then
                    return Stat.Value
                end
            end

            return nil
        end

        local function CollectScales(Entries)
            local Values = {}

            for _, Entry in ipairs(Entries) do
                for _, Stat in ipairs(Entry.Stats) do
                    if Stat.Numeric then
                        Values[Stat.Key] = Values[Stat.Key] or {}
                        table.insert(Values[Stat.Key], Stat.Value)
                    end
                end
            end

            local Scales = {}

            for Key, List in pairs(Values) do
                table.sort(List, function(A, B)
                    return A > B
                end)

                Scales[Key] = { Max = List[1], Sorted = List }
            end

            return Scales
        end

        --// One scale over every mob, and one per kind, so a mob's bars are
        --// measured against other mobs and a boss's against other bosses.
        local function BuildScales()
            local ByKind = {}

            for _, Entry in ipairs(S.Entries) do
                ByKind[Entry.Kind] = ByKind[Entry.Kind] or {}
                table.insert(ByKind[Entry.Kind], Entry)
            end

            S.Scales = CollectScales(S.Entries)
            S.KindScales = {}

            for Kind, Entries in pairs(ByKind) do
                S.KindScales[Kind] = CollectScales(Entries)
            end
        end

        local function FindScale(Stat, Kind)
            if not Stat.Numeric then
                return nil
            end

            if Kind then
                local Scales = S.KindScales[Kind]
                return Scales and Scales[Stat.Key]
            end

            return S.Scales[Stat.Key]
        end

        --// Fraction of the strongest value (0..1) and the rank (1 = highest)
        --// among the mobs of Kind that have this stat, or among every mob
        --// when Kind is nil.
        function Dictionary.GetScale(Stat, Kind)
            local Scale = FindScale(Stat, Kind)

            if not Scale then
                return 0, nil, 0
            end

            local Fraction = Scale.Max > 0 and math.clamp(Stat.Value / Scale.Max, 0, 1) or 0
            local Rank = table.find(Scale.Sorted, Stat.Value)
            return Fraction, Rank, #Scale.Sorted
        end

        --// 0..1: the mean of where each threat stat ranks among every mob
        --// (1 = the highest of all). Ranks rather than values, so one huge
        --// boss does not make every other mob look harmless.
        function Dictionary.GetThreat(Entry)
            local Total, Count = 0, 0

            for _, Stat in ipairs(Entry.Stats) do
                if Stat.Numeric and Dictionary.IsThreatStat(Stat) then
                    local _, Rank, Size = Dictionary.GetScale(Stat)

                    if Rank then
                        Total += Size > 1 and (Size - Rank) / (Size - 1) or 1
                        Count += 1
                    end
                end
            end

            return Count > 0 and Total / Count or 0
        end

        --// Adds (or updates) the AwardParam stat of a HealthPercent mob
        --// once its AwardParam is known. True when the entry changed.
        local function ApplyAwardParam(Entry)
            local Param = S.AwardParams[Entry.Name]

            if type(Param) ~= "number" or Dictionary.GetStat(Entry, "Config.AwardType") ~= AWARD_TYPE_HEALTH_PERCENT then
                return false
            end

            for _, Stat in ipairs(Entry.Stats) do
                if Stat.Key == AWARD_PARAM_KEY then
                    if Stat.Value == Param then
                        return false
                    end

                    Stat.Value = Param
                    return true
                end
            end

            table.insert(Entry.Stats, {
                Key = AWARD_PARAM_KEY,
                Label = AWARD_PARAM_LABEL,
                Value = Param,
                Group = "Rewards",
                Numeric = true,
            })

            return true
        end

        local function Apply(Raw)
            local Entries, ByName = {}, {}

            for Name, Data in pairs(Raw) do
                if type(Name) == "string" and type(Data) == "table" then
                    local Entry = ReadEntry(Name, Data)
                    ApplyAwardParam(Entry)
                    table.insert(Entries, Entry)
                    ByName[Name] = Entry
                end
            end

            table.sort(Entries, function(A, B)
                local HealthA = Dictionary.GetStat(A, "Humanoid.MaxHealth") or 0
                local HealthB = Dictionary.GetStat(B, "Humanoid.MaxHealth") or 0

                if HealthA ~= HealthB then
                    return HealthA < HealthB
                end

                return A.Name < B.Name
            end)

            S.Entries = Entries
            S.ByName = ByName
            BuildScales()
        end

        local function Finish(ErrorMessage)
            S.Loading = false
            S.Error = ErrorMessage

            if S.OnLoaded then
                S.OnLoaded()
            end
        end

        --// Asks the server for the dictionary in the background. The server
        --// builds it once and keeps it, so asking again is cheap.
        function Dictionary:Load()
            if S.Loading then
                return
            end

            local Remote = Replicated:FindFirstChild(REMOTE_NAME, true)

            if not Remote or not Remote:IsA("RemoteFunction") then
                Finish("Mob dictionary is not available in this place")
                return
            end

            S.Loading = true
            S.Error = nil
            S.LoadToken += 1

            local Token = S.LoadToken

            --// InvokeServer can wait forever; give up on it after a while.
            task.delay(LOAD_TIMEOUT, function()
                if Context.Lifetime.Alive and S.Loading and S.LoadToken == Token then
                    S.LoadToken += 1
                    Finish("The server did not answer. Press RELOAD to try again.")
                end
            end)

            task.spawn(function()
                local Ok, Result = pcall(Remote.InvokeServer, Remote, REMOTE_ARGUMENT)

                --// Stopped, timed out, or a newer load is running.
                if not Context.Lifetime.Alive or S.LoadToken ~= Token then
                    return
                end

                if not Ok then
                    Finish("Could not read the mob dictionary: " .. tostring(Result))
                    return
                end

                if type(Result) ~= "table" then
                    Finish("The server sent no mob dictionary")
                    return
                end

                Apply(Result)
                S.Loaded = true
                Finish(nil)
            end)
        end

        function Dictionary:GetAll()
            return S.Entries
        end

        function Dictionary:Get(Name)
            return S.ByName[Name]
        end

        ------------------------------------------------------------------------
        --// Drops and luck
        ------------------------------------------------------------------------

        --// A spawned mob is a full clone of its ServerStorage model, so its
        --// Config.MaxDrops can be read here (the dictionary leaves it out).
        --// Each child is one item: Value = how many times it is rolled,
        --// Rarity = 1 in N.
        local function ReadDrops(MaxDrops)
            local Drops = {}

            for _, Item in ipairs(MaxDrops:GetChildren()) do
                local Rarity = Item:FindFirstChild("Rarity")
                local Value = Rarity and Rarity:IsA("ValueBase") and tonumber(Rarity.Value)

                if Value and Value > 0 and Item.Name ~= "" then
                    table.insert(Drops, {
                        Name = Item.Name,
                        Rarity = Value,
                        Rounds = Item:IsA("ValueBase") and tonumber(Item.Value) or 0,
                    })
                end
            end

            table.sort(Drops, function(A, B)
                if A.Rarity ~= B.Rarity then
                    return A.Rarity < B.Rarity
                end

                return A.Name < B.Name
            end)

            return Drops
        end

        --// One string per drop list, to tell whether two lists are the same.
        --// Numbers are cut by DROPS_SIGNATURE_FORMAT so a value that lost a
        --// last digit going through JSON still matches the live one.
        local function DropsSignature(Drops)
            local Parts = {}

            for _, Drop in ipairs(Drops) do
                table.insert(Parts, string.format(DROPS_SIGNATURE_FORMAT, Drop.Name, Drop.Rarity, Drop.Rounds))
            end

            return table.concat(Parts, "|")
        end

        --// A saved drop list, or nil when it is not one.
        local function NormalizeSavedDrops(Raw)
            if type(Raw) ~= "table" then
                return nil
            end

            local Drops = {}

            for _, Drop in ipairs(Raw) do
                local Rarity = type(Drop) == "table" and tonumber(Drop.Rarity)

                if Rarity and Rarity > 0 and type(Drop.Name) == "string" and Drop.Name ~= "" then
                    table.insert(Drops, {
                        Name = Drop.Name,
                        Rarity = Rarity,
                        Rounds = tonumber(Drop.Rounds) or 0,
                    })
                end
            end

            return Drops
        end

        --// Fills S.Drops from DROPS_FILE before any mob is seen.
        local function LoadSavedDrops()
            if not AICProfile.CanUseFileStorage() then
                return
            end

            local CheckSuccess, Exists = pcall(isfile, DROPS_FILE)

            if not CheckSuccess or not Exists then
                return
            end

            local Success, Decoded = pcall(function()
                return HttpService:JSONDecode(readfile(DROPS_FILE))
            end)

            if not Success or type(Decoded) ~= "table" or type(Decoded.Mobs) ~= "table" then
                warn("AutoFarm mob drops read failed:", Decoded)
                return
            end

            for Name, Raw in pairs(Decoded.Mobs) do
                local Drops = type(Name) == "string" and NormalizeSavedDrops(Raw)

                if Drops then
                    S.Drops[Name] = Drops
                    S.SavedSignatures[Name] = DropsSignature(Drops)
                end
            end

            if type(Decoded.AwardParams) == "table" then
                for Name, Param in pairs(Decoded.AwardParams) do
                    if type(Name) == "string" and tonumber(Param) then
                        S.AwardParams[Name] = tonumber(Param)
                    end
                end
            end
        end

        --// Writes every non-empty drop list (an empty one may just be a mob
        --// that had not replicated, so it is not kept between runs).
        local function WriteSavedDrops()
            if not AICProfile.CanUseFileStorage() then
                return false
            end

            AICProfile.EnsureProfileFolder()

            local Mobs = {}

            for Name, Drops in pairs(S.Drops) do
                if #Drops > 0 then
                    Mobs[Name] = Drops
                end
            end

            local Success, Raw = pcall(function()
                return HttpService:JSONEncode({ Version = DROPS_FILE_VERSION, Mobs = Mobs, AwardParams = S.AwardParams })
            end)

            if not Success then
                warn("AutoFarm mob drops encode failed:", Raw)
                return false
            end

            local WriteSuccess, WriteError = pcall(writefile, DROPS_FILE, Raw)

            if not WriteSuccess then
                warn("AutoFarm mob drops save failed:", WriteError)
                return false
            end

            for Name, Drops in pairs(Mobs) do
                S.SavedSignatures[Name] = DropsSignature(Drops)
            end

            return true
        end

        --// Reads a live mob's drops (once per run once they are non-empty)
        --// into S.Drops. Returns whether S.Drops changed, and whether that
        --// change needs saving: not saved yet, or different from the save.
        local function RecordLiveDrops(Name, Config)
            if S.CheckedLive[Name] then
                return false, false
            end

            local MaxDrops = Config:FindFirstChild("MaxDrops")
            local Drops = MaxDrops and ReadDrops(MaxDrops) or {}

            --// No MaxDrops: it drops nothing. An empty read is read again
            --// from the next one, in case this one had not finished
            --// replicating, and never replaces a known list.
            if #Drops == 0 then
                if S.Drops[Name] then
                    return false, false
                end

                S.Drops[Name] = Drops
                return true, false
            end

            S.CheckedLive[Name] = true

            if S.SavedSignatures[Name] == DropsSignature(Drops) then
                return false, false
            end

            S.Drops[Name] = Drops
            return true, true
        end

        --// A live HealthPercent mob's AwardParam into S.AwardParams and its
        --// entry. Returns whether it changed, and so needs saving.
        local function RecordLiveAwardParam(Name, Config)
            local AwardType = Config:FindFirstChild("AwardType")

            if not AwardType or not AwardType:IsA("StringValue") or AwardType.Value ~= AWARD_TYPE_HEALTH_PERCENT then
                return false
            end

            local Param = tonumber(AwardType:GetAttribute(AWARD_PARAM_ATTRIBUTE))

            if not Param or S.AwardParams[Name] == Param then
                return false
            end

            S.AwardParams[Name] = Param

            local Entry = S.ByName[Name]

            if Entry and ApplyAwardParam(Entry) then
                BuildScales()
            end

            return true
        end

        --// Mobs alive in workspace.Mobs by Config.Entity (the dictionary
        --// name; the model itself is renamed "Mob<tick>"). The first one of
        --// each kind seen records its drops in S.Drops, and DROPS_FILE is
        --// rewritten only when that added or changed a saved mob.
        --// True when S.Drops changed.
        function Dictionary:ScanLive()
            local Counts = {}
            local NewDrops = false
            local Folder = workspace:FindFirstChild("Mobs")

            for _, Mob in (Folder and Folder:GetChildren() or {}) do
                local Config = Mob:IsA("Model") and Mob:FindFirstChild("Config")
                local Entity = Config and Config:FindFirstChild("Entity")

                if not Entity or not Entity:IsA("StringValue") or Entity.Value == "" then
                    continue
                end

                local Name = Entity.Value
                Counts[Name] = (Counts[Name] or 0) + 1

                local Changed, NeedsSave = RecordLiveDrops(Name, Config)
                local NewAwardParam = RecordLiveAwardParam(Name, Config)
                NewDrops = NewDrops or Changed or NewAwardParam
                S.SavePending = S.SavePending or NeedsSave or NewAwardParam
            end

            S.Live = Counts

            if S.SavePending and WriteSavedDrops() then
                S.SavePending = false
            end

            return NewDrops
        end

        function Dictionary:GetLive(Name)
            return S.Live[Name] or 0
        end

        --// nil until a live one has been seen (this run or an earlier one).
        function Dictionary:GetDrops(Name)
            return S.Drops[Name]
        end

        --// Percent of health to deal for a reward, for a HealthPercent mob
        --// once a live one has been seen; nil otherwise.
        function Dictionary:GetAwardParam(Name)
            return S.AwardParams[Name]
        end

        --// Most luck that counts (CoreCommons.PHYSICAL_STAT_MAX). Required in
        --// the background once, since a require can wait; DEFAULT_LUCK_CAP
        --// until then or when it cannot be read.
        local function GetLuckCap()
            if S.LuckCap then
                return S.LuckCap
            end

            if not S.LuckCapRequested then
                S.LuckCapRequested = true

                task.spawn(function()
                    local Commons = Replicated:FindFirstChild("CoreCommons")
                    local Ok, Module = false, nil

                    if Commons and Commons:IsA("ModuleScript") then
                        Ok, Module = pcall(require, Commons)
                    end

                    local Cap = Ok and type(Module) == "table" and tonumber(Module.PHYSICAL_STAT_MAX)
                    S.LuckCap = Cap and Cap > 0 and Cap or DEFAULT_LUCK_CAP
                end)
            end

            return S.LuckCap or DEFAULT_LUCK_CAP
        end

        --// The player's Luck stat, the cap, and the percent it adds to every
        --// drop roll (Luck / 100, Luck capped).
        function Dictionary.GetLuck()
            local Stats = Context.Player:FindFirstChild("PlayerStats")
            local Luck = Stats and Stats:FindFirstChild("Luck")
            local Value = Luck and Luck:IsA("ValueBase") and tonumber(Luck.Value) or 0
            local Cap = GetLuckCap()
            return Value, Cap, math.clamp(Value, 0, Cap) / LUCK_DIVISOR
        end

        --// The server rolls 1..100 and drops when the roll <= Odds + Luck.
        local function RollChance(Odds)
            return math.clamp(math.floor(Odds + ROUNDING_EPSILON), 0, 100) / 100
        end

        --// Odds of one item from one kill, as the server rolls it: Rounds
        --// rolls of 100 / Rarity (+ Luck%); until the item has dropped, roll
        --// N's odds are multiplied by N. Returns the chance of at least one
        --// (0..1) and the expected count.
        function Dictionary.GetDropOdds(Drop, LuckPercent)
            local Odds = 100 / Drop.Rarity
            local Rounds = math.min(Drop.Rounds, MAX_ROUNDS)
            local Missed, Expected = 1, 0
            local Again = RollChance(Odds + LuckPercent)

            for Round = 1, Rounds do
                local First = RollChance(Odds * Round + LuckPercent)
                Expected += Missed * First + (1 - Missed) * Again
                Missed *= 1 - First
            end

            return 1 - Missed, Expected
        end

        LoadSavedDrops()

        --// Mobs that come and go while the window is closed are recorded too.
        task.spawn(function()
            while Context.Lifetime.Alive do
                local Ok, ScanError = pcall(Dictionary.ScanLive, Dictionary)

                if not Ok then
                    warn("AutoFarm mob drops scan failed:", ScanError)
                end

                task.wait(LIVE_SCAN_INTERVAL)
            end
        end)

        return Dictionary
    end,
}
]======],
	["Features/MobGather.lua"] = [======[
-- MobGather pulls a pack of mobs together before using the skill on them.
--
--   Idle   picks a pack: at least GATHER_MIN_MOBS valid mobs within
--          GATHER_RADIUS of the nearest one, none being fought by another
--          player. Fewer than that and the farm fights as usual.
--   Tag    runs to each mob in turn and hits it once, so it follows us,
--          then goes on to the next (GATHER_MAX_MOBS at most).
--   Kite   backs off KITE_DISTANCE away from the pack and waits there for
--          the tagged mobs to bunch up within the skill's range.
--   Burst  faces the pack and uses the skill once it is ready.
--   Fight  hands the frame back to normal combat until the pack is down.
--
-- Any step that takes too long, a pack that stops following, a duel, or
-- health under COMBAT_SKILL_MIN_HP_PERCENT ends the round; the farm then
-- fights as usual and the next round waits ROUND_COOLDOWN. The health
-- retreat, skill dodging, Auto Block and the waypoint route all run before
-- this, as AutoFarming calls GatherStep after them.
return {
    Name = "MobGather",
    IsFeature = true,
    Dependencies = {"Runtime", "SaveConfig", "Components", "CombatUtils", "Targeting", "Navigation", "Combat", "WalkController"},

    Start = function(Context)
        local Runtime = Context.Runtime
        local Services = Context.Services
        local Players = Services.Players
        local Player = Context.Player
        local CONFIG = Context.CONFIG
        local Feature = Context.Feature
        local AICCombat = Context.AICCombat
        local AICCombatUtils = Context.AICCombatUtils
        local AICFeature = Context.AICFeature
        local AICUI = Context.AICUI
        local UIRef = Context.UIRef
        local Movement = Context.WalkController

        --// Seconds to reach and hit one mob before it is dropped from the pack.
        local TAG_TIMEOUT = 6
        local KITE_TIMEOUT = 10
        --// Waiting at the kite spot for the pack before using the skill anyway.
        local GATHER_WAIT = 4
        --// Facing the pack and waiting for the skill to come off cooldown.
        local BURST_TIMEOUT = 4
        local FIGHT_TIMEOUT = 25
        local ROUND_COOLDOWN = 4
        --// How far the kite backs off from the pack.
        local KITE_DISTANCE = 12
        local KITE_ARRIVAL = 3
        --// A tagged mob farther than this from us has stopped following...
        local LOST_DISTANCE = 35
        --// ...once it has been that far this long.
        local LOST_SECONDS = 3
        --// Kite directions tried, in degrees off straight away from the pack.
        local KITE_ANGLES = { 0, 35, -35, 70, -70, 110, -110 }

        local Gather = {
            Name = "MobGather",
            IsFeature = true,
            S = {
                State = "Idle",
                StateSince = 0,
                CooldownUntil = 0,
                --// The pack in tagging order.
                Pack = {},
                Tagged = {},
                TagIndex = 1,
                TagStart = 0,
                LostSince = {},
                KitePoint = nil,
                ArrivedAt = nil,
            },
        }

        local S = Gather.S

        ------------------------------------------------------------------------
        --// Helpers
        ------------------------------------------------------------------------

        local function SetState(State, now)
            S.State = State
            S.StateSince = now
        end

        local function GetRoot(Mob)
            return Mob and Mob.Parent and Mob:FindFirstChild("HumanoidRootPart")
        end

        local function IsAlive(Mob)
            local Humanoid = Mob and Mob.Parent and Mob:FindFirstChildOfClass("Humanoid")
            return Humanoid ~= nil and Humanoid.Health > 0 and GetRoot(Mob) ~= nil
        end

        --// Another player is fighting it: leave it to them.
        local function IsClaimedByOther(Mob)
            local LastAttacker = Mob:FindFirstChild("LastAttacker")
            local Value = LastAttacker and LastAttacker.Value
            return Value ~= nil and Value ~= Player
        end

        local function IsPackCandidate(Mob)
            return not Players:GetPlayerFromCharacter(Mob)
                and AICCombat.IsTargetLockValid(Mob)
                and not IsClaimedByOther(Mob)
        end

        local function GetHealthPercent()
            local _, Humanoid = Runtime:GetCharacter()

            if not Humanoid or Humanoid.MaxHealth <= 0 then
                return 0
            end

            return Humanoid.Health / Humanoid.MaxHealth * 100
        end

        --// Tagged mobs still alive and still following.
        local function GetFollowers(now, RootPart)
            local Followers = {}

            for _, Mob in ipairs(S.Pack) do
                local MobRoot = GetRoot(Mob)

                if S.Tagged[Mob] and IsAlive(Mob) and MobRoot then
                    if AICCombatUtils.GetHorizontalDistance(MobRoot.Position, RootPart.Position) > LOST_DISTANCE then
                        S.LostSince[Mob] = S.LostSince[Mob] or now
                    else
                        S.LostSince[Mob] = nil
                    end

                    if now - (S.LostSince[Mob] or now) < LOST_SECONDS then
                        table.insert(Followers, Mob)
                    end
                end
            end

            return Followers
        end

        local function GetCentroid(Mobs)
            local Sum, Count = Vector3.zero, 0

            for _, Mob in ipairs(Mobs) do
                local MobRoot = GetRoot(Mob)

                if MobRoot then
                    Sum += MobRoot.Position
                    Count += 1
                end
            end

            return Count > 0 and Sum / Count or nil
        end

        local function GetNearest(Mobs, Position)
            local Best, BestDistance = nil, math.huge

            for _, Mob in ipairs(Mobs) do
                local MobRoot = GetRoot(Mob)
                local Distance = MobRoot and AICCombatUtils.GetHorizontalDistance(MobRoot.Position, Position) or math.huge

                if Distance < BestDistance then
                    Best, BestDistance = Mob, Distance
                end
            end

            return Best, BestDistance
        end

        local function CountWithin(Mobs, Position, Radius)
            local Count = 0

            for _, Mob in ipairs(Mobs) do
                local MobRoot = GetRoot(Mob)

                if MobRoot and AICCombatUtils.GetHorizontalDistance(MobRoot.Position, Position) <= Radius then
                    Count += 1
                end
            end

            return Count
        end

        local function SetStatus(Text)
            if UIRef.GatherStatusLabel then
                UIRef.GatherStatusLabel:Set("GATHER  " .. Text)
            end
        end

        ------------------------------------------------------------------------
        --// Rounds
        ------------------------------------------------------------------------

        function Gather:Reset(now)
            table.clear(S.Pack)
            table.clear(S.Tagged)
            table.clear(S.LostSince)
            S.TagIndex = 1
            S.KitePoint = nil
            S.ArrivedAt = nil
            SetState("Idle", now or os.clock())
            Movement:Reset()
        end

        local function EndRound(now, Reason)
            Gather:Reset(now)
            S.CooldownUntil = now + ROUND_COOLDOWN
            SetStatus(Reason)
        end

        --// Nearest valid mob first, then repeatedly the pack member nearest
        --// the last one, so the tagging run does not zig-zag.
        local function FindPack(RootPart)
            local Candidates = {}

            for Mob in pairs(AICCombat.S.ValidMobs) do
                if IsPackCandidate(Mob) then
                    table.insert(Candidates, Mob)
                end
            end

            local Seed = GetNearest(Candidates, RootPart.Position)
            local SeedRoot = GetRoot(Seed)

            if not SeedRoot then
                return nil
            end

            local Radius = tonumber(CONFIG.GATHER_RADIUS) or 40
            local Remaining = {}

            for _, Mob in ipairs(Candidates) do
                local MobRoot = GetRoot(Mob)

                if MobRoot and AICCombatUtils.GetHorizontalDistance(MobRoot.Position, SeedRoot.Position) <= Radius then
                    table.insert(Remaining, Mob)
                end
            end

            if #Remaining < (tonumber(CONFIG.GATHER_MIN_MOBS) or 3) then
                return nil
            end

            local Pack = {}
            local From = RootPart.Position
            local MaxMobs = tonumber(CONFIG.GATHER_MAX_MOBS) or 5

            while #Remaining > 0 and #Pack < MaxMobs do
                local Next = GetNearest(Remaining, From)
                table.remove(Remaining, table.find(Remaining, Next))
                table.insert(Pack, Next)
                From = GetRoot(Next).Position
            end

            return Pack
        end

        --// A spot KITE_DISTANCE away from the pack, inside the farm zone and
        --// out of deadzones and water, with an open walk to it.
        local function FindKitePoint(RootPart, Followers)
            local Center = GetCentroid(Followers)

            if not Center then
                return nil
            end

            local Away = RootPart.Position - Center
            Away = Vector3.new(Away.X, 0, Away.Z)
            Away = Away.Magnitude > 0.01 and Away.Unit or RootPart.CFrame.LookVector * -1

            for _, Angle in ipairs(KITE_ANGLES) do
                local Direction = CFrame.Angles(0, math.rad(Angle), 0):VectorToWorldSpace(Away)
                local Point = RootPart.Position + Direction * KITE_DISTANCE

                if AICCombatUtils.IsInsideFarmArea(Point)
                    and not AICCombatUtils.IsInsideFarmDeadzone(Point)
                    and not AICCombatUtils.IsWaterAtPosition(Point)
                    and not AICCombatUtils.IsPathThroughDeadzone(Point)
                    and AICCombatUtils.IsPathClear(Point)
                then
                    return Point
                end
            end

            return nil
        end

        local function StepIdle(now, RootPart)
            if now < S.CooldownUntil then
                return false
            end

            if GetHealthPercent() < (tonumber(CONFIG.COMBAT_SKILL_MIN_HP_PERCENT) or 50) then
                SetStatus("WAITING FOR HEALTH")
                return false
            end

            local Pack = FindPack(RootPart)

            if not Pack then
                SetStatus("NO PACK")
                return false
            end

            S.Pack = Pack
            S.TagIndex = 1
            S.TagStart = now
            SetState("Tag", now)
            return true
        end

        local function StepTag(now, RootPart)
            --// Skip anything dead, gone, taken by another player, or already
            --// following us (hit by the fight before the round).
            while S.TagIndex <= #S.Pack do
                local Mob = S.Pack[S.TagIndex]
                local LastAttacker = IsAlive(Mob) and Mob:FindFirstChild("LastAttacker")

                if not IsAlive(Mob) or IsClaimedByOther(Mob) then
                    S.TagIndex += 1
                    S.TagStart = now
                elseif LastAttacker and LastAttacker.Value == Player then
                    S.Tagged[Mob] = true
                    S.TagIndex += 1
                    S.TagStart = now
                else
                    break
                end
            end

            local Mob = S.Pack[S.TagIndex]

            if not Mob then
                SetState("Kite", now)
                return true
            end

            if now - S.TagStart > TAG_TIMEOUT then
                S.TagIndex += 1
                S.TagStart = now
                return true
            end

            SetStatus(string.format("TAG  %d / %d", S.TagIndex, #S.Pack))

            if AICFeature.EnsureWeaponDrawn and AICFeature.EnsureWeaponDrawn(now) then
                Movement:Hold()
                return true
            end

            local MobRoot = GetRoot(Mob)
            local Distance = AICCombatUtils.GetHorizontalDistance(MobRoot.Position, RootPart.Position)

            if Distance <= AICCombat.GetCombatAttackRange(Mob) then
                Movement:Hold()
                AICCombat.FaceGoblin(Mob)

                --// One swing is enough to make it follow; go on to the next.
                if AICCombat.RetreatAttack(Mob, now) then
                    S.Tagged[Mob] = true
                    S.TagIndex += 1
                    S.TagStart = now
                end

                return true
            end

            if Movement:MoveTo(MobRoot.Position, { Ignore = Mob }) == "failed" then
                S.TagIndex += 1
                S.TagStart = now
            end

            return true
        end

        local function StepKite(now, RootPart, Followers)
            if #Followers == 0 then
                EndRound(now, "PACK LOST")
                return false
            end

            local SkillRange = tonumber(CONFIG.COMBAT_SKILL_RANGE) or 15
            local Wanted = math.min(tonumber(CONFIG.GATHER_MIN_MOBS) or 3, #Followers)

            --// Bunched up already: no need to back off further.
            if CountWithin(Followers, RootPart.Position, SkillRange) >= Wanted
                and now - S.StateSince > 0.5
            then
                SetState("Burst", now)
                return true
            end

            S.KitePoint = S.KitePoint or FindKitePoint(RootPart, Followers)

            local Arrived = not S.KitePoint
                or AICCombatUtils.GetHorizontalDistance(S.KitePoint, RootPart.Position) <= KITE_ARRIVAL

            if Arrived then
                S.ArrivedAt = S.ArrivedAt or now
                Movement:Hold()
                AICCombat.FaceGoblin((GetNearest(Followers, RootPart.Position)))
                SetStatus(string.format("GATHERING  %d / %d", CountWithin(Followers, RootPart.Position, SkillRange), #Followers))

                if now - S.ArrivedAt > GATHER_WAIT then
                    SetState("Burst", now)
                end

                return true
            end

            if now - S.StateSince > KITE_TIMEOUT then
                SetState("Burst", now)
                return true
            end

            SetStatus("KITE")
            Movement:MoveTo(S.KitePoint)
            return true
        end

        local function StepBurst(now, RootPart, Followers)
            local Nearest = GetNearest(Followers, RootPart.Position)

            if not Nearest then
                EndRound(now, "PACK LOST")
                return false
            end

            Movement:Hold()
            AICCombat.FaceGoblin(Nearest)
            SetStatus("BURST")

            if AICFeature.EnsureWeaponDrawn and AICFeature.EnsureWeaponDrawn(now) then
                return true
            end

            local SkillReady = now >= AICCombat.S.COMBAT_NEXT_SKILL_TIME

            if SkillReady and AICCombat.InvokeCombatInput("SkillButton") then
                AICCombat.S.LAST_SKILL_TIME = now
                AICCombat.S.COMBAT_NEXT_SKILL_TIME = now + CONFIG.SKILL_INTERVAL
                SetState("Fight", now)
                return true
            end

            --// The skill would not come: fight them as they are.
            if now - S.StateSince > BURST_TIMEOUT then
                SetState("Fight", now)
            end

            return true
        end

        --// Normal combat fights the pack; this only watches for the end.
        local function StepFight(now, Followers)
            SetStatus(string.format("FIGHT  %d LEFT", #Followers))

            if #Followers == 0 or now - S.StateSince > FIGHT_TIMEOUT then
                EndRound(now, "DONE")
            end

            return false
        end

        --// Called by AutoFarming once the route is walked, after the health
        --// retreat and skill dodging. True while gathering owns this frame.
        function AICFeature.GatherStep(now)
            if not Feature.MobGather.Enabled then
                return false
            end

            local _, Humanoid, RootPart = Runtime:GetCharacter()

            if not Humanoid or not RootPart then
                return false
            end

            if S.State ~= "Idle" and AICCombat.IsInDuel() then
                EndRound(now, "DUEL")
                return false
            end

            if S.State == "Idle" then
                return StepIdle(now, RootPart)
            elseif S.State == "Tag" then
                return StepTag(now, RootPart)
            end

            local Followers = GetFollowers(now, RootPart)

            if S.State == "Kite" then
                return StepKite(now, RootPart, Followers)
            elseif S.State == "Burst" then
                return StepBurst(now, RootPart, Followers)
            end

            return StepFight(now, Followers)
        end

        ------------------------------------------------------------------------
        --// UI
        ------------------------------------------------------------------------

        local Section = UIRef.GatherSection

        AICUI.BindFeatureToggle("MobGather", "Gather Mobs", function(Enabled)
            Gather:Reset()
            SetStatus(Enabled and "IDLE" or "OFF")
        end, Section)

        UIRef.GatherStatusLabel = Section:AddLabel("GATHER  OFF")
        UIRef.GatherMinSlider = AICUI.AddSettingSlider(Section, "Min Mobs", "GATHER_MIN_MOBS", true)
        UIRef.GatherMaxSlider = AICUI.AddSettingSlider(Section, "Max Mobs", "GATHER_MAX_MOBS", true)
        UIRef.GatherRadiusSlider = AICUI.AddSettingSlider(Section, "Gather Radius", "GATHER_RADIUS", true)

        Context.Connect(Player.CharacterAdded, function()
            Gather:Reset()
        end)

        function Gather:Update()
            if not Feature.MobGather.Enabled and S.State ~= "Idle" then
                Gather:Reset()
            end
        end

        return Gather
    end,
}
]======],
	["Features/PartySystem.lua"] = [======[
-- PartySystem follows a Leader between servers.
--
-- A Leader is picked from the players in the server. While the Leader is in
-- the server the farm runs as normal, strangers included. Once the Leader is
-- gone the character is reset and held still, and about a second later the
-- game's ChatEvent remote is fired with "tp friend <Leader>". A try succeeds
-- once the Leader is in the same server; after PARTY_TP_ATTEMPTS failed tries
-- it gives up for PARTY_FAILED_COOLDOWN seconds, during which Auto Block
-- handles intruders.
return {
    Name = "PartySystem",
    IsFeature = true,
    Dependencies = {"Runtime", "ProfileManager", "Components", "AutoBlock"},

    Start = function(Context)
        local Runtime = Context.Runtime
        local Services = Context.Services
        local Players = Services.Players
        local Replicated = Services.Replicated
        local Player = Context.Player
        local CONFIG = Context.CONFIG
        local FeatureState = Context.Feature
        local AICFeature = Context.AICFeature
        local AICProfile = Context.AICProfile
        local AICUI = Context.AICUI
        local UIRef = Context.UIRef
        local NotifyAction = Context.NotifyAction

        local Feature = {
            Name = "PartySystem",
            IsFeature = true,
        }

        AICFeature.S.Party = {
            --// True while the farm loop must stand still.
            Holding = false,
            --// True while a reset / Tp sequence is running.
            Busy = false,
            CooldownUntil = 0,
            LastCheck = 0,
            AttemptedToFindTeleporter = 0
        }

        local State = AICFeature.S.Party

        local function GetLeader()
            local Leader = CONFIG.PARTY_LEADER

            if type(Leader) == "table" and type(Leader.Name) == "string" and Leader.Name ~= "" then
                return Leader
            end

            return nil
        end

        local function IsActive()
            return FeatureState.PartySystem.Enabled == true and GetLeader() ~= nil
        end

        local function IsLeaderPlayer(OtherPlayer)
            local Leader = GetLeader()

            if not Leader or not OtherPlayer then
                return false
            end

            if Leader.UserId then
                return OtherPlayer.UserId == Leader.UserId
            end

            return OtherPlayer.Name == Leader.Name
        end

        local function IsLeaderInServer()
            for _, OtherPlayer in ipairs(Players:GetPlayers()) do
                if IsLeaderPlayer(OtherPlayer) then
                    return true
                end
            end

            return false
        end

        local function SetStatus(Text)
            State.Status = Text

            if UIRef.PartyStatusLabel then
                UIRef.PartyStatusLabel:Set("STATUS:  " .. tostring(Text))
            end
        end

        --// Asks the game to Tp us to the Leader through its ChatEvent remote.
        local function RequestTeleport(LeaderName)
            return pcall(function()
                local ChatEvent = Replicated:FindFirstChild("ChatEvent", true)
                local TeleportEvent = Replicated:FindFirstChild("TeleportEvent", true)

                assert(TeleportEvent, "no TeleportEvent remote")
                TeleportEvent:FireServer(0)
                task.delay(0.5, function()
                    assert(ChatEvent, "no ChatEvent remote")
                    ChatEvent:FireServer("Party", "tp friend " .. LeaderName)
                end)    
                    
                -- if workspace.GameLoader.Options.Floor.Value ~= 1 then
                --     local UseConsumable = Replicated:FindFirstChild("UseConsumable", true)
                --     local PlayerStats = Player:FindFirstChild("PlayerStats")
                --     local Inventory = PlayerStats:FindFirstChild("Inventory")
                --     local TeleportCrystal, Amount = AICUI.GetItem(Inventory.Value,"Teleport Crystal")
                --     if UseConsumable and PlayerStats and Inventory and Amount > 0 then
                --         UseConsumable:InvokeServer(TeleportCrystal)
                --     elseif Amount <= 0 then
                --         NotifyAction("Party", "Insufficient "..TeleportCrystal.." in inventory.")
                --     end
                -- else
                --     -- assert(TeleportEvent, "no TeleportEvent remote")
                --     -- TeleportEvent:FireServer(0)
                --     task.delay(0.5, function()
                --         assert(ChatEvent, "no ChatEvent remote")
                --         ChatEvent:FireServer("Party", "tp friend " .. LeaderName)
                --     end)     
                -- end
            end)
        end

        local function ResetCharacter()
            local _, Humanoid = Runtime:GetCharacter()

            if not Humanoid or Humanoid.Health <= 0 then
                return
            end

            local Respawned = false
            local Connection = Player.CharacterAdded:Connect(function()
                Respawned = true
            end)

            Humanoid.Health = 0

            local Deadline = os.clock() + (tonumber(CONFIG.PARTY_RESPAWN_TIMEOUT) or 10)

            repeat
                task.wait(0.25)
            until Respawned or os.clock() > Deadline

            Connection:Disconnect()

            --// Give the new character a moment to finish loading.
            task.wait(1)
        end

        local function Release(StatusText)
            State.Holding = false
            State.Busy = false
            SetStatus(StatusText)
        end

        --// Runs only once the Leader has left the server.
        local function RunFollow()
            State.Holding = true
            SetStatus("RESETTING")
            ResetCharacter()

            --// The Leader came back while we were respawning.
            if IsLeaderInServer() then
                Release("WITH LEADER")
                return
            end

            local Leader = GetLeader()
            local Attempts = math.max(1, tonumber(CONFIG.PARTY_TP_ATTEMPTS) or 3)
            local Timeout = tonumber(CONFIG.PARTY_TP_ATTEMPT_TIMEOUT) or 15

            for Attempt = 1, Attempts do
                if not IsActive() then
                    Release("IDLE")
                    return
                end

                SetStatus(string.format("TP FRIEND %s  (%d/%d)", Leader.Name, Attempt, Attempts))

                if not RequestTeleport(Leader.Name) then
                    NotifyAction("Party", "Could not fire ChatEvent")
                end

                --// A successful Tp moves us to the Leader's server and this
                --// script ends there; the Leader showing up here also counts.
                local Deadline = os.clock() + Timeout

                repeat
                    task.wait(1)
                until IsLeaderInServer() or os.clock() > Deadline or not IsActive()

                if IsLeaderInServer() then
                    Release("WITH LEADER")
                    return
                end
            end

            State.CooldownUntil = os.clock() + (tonumber(CONFIG.PARTY_FAILED_COOLDOWN) or 60)
            NotifyAction("Party", "Tp to " .. Leader.Name .. " failed after " .. Attempts .. " tries")
            Release("TP FAILED, RETRY LATER")
        end

        --// Auto Block stays out of the way while a Leader is being followed,
        --// except during the cooldown after a failed Tp.
        function AICFeature.PartyHandlesIntruders()
            return IsActive() and os.clock() >= State.CooldownUntil
        end

        function AICFeature.IsPartyHolding()
            return State.Holding == true
        end

        function Feature:Update()
            local now = os.clock()

            if now - State.LastCheck < (tonumber(CONFIG.PARTY_CHECK_INTERVAL) or 1) then
                return
            end

            State.LastCheck = now

            if State.Busy then
                return
            end

            if not IsActive() then
                if State.Holding then
                    Release("IDLE")
                end

                return
            end

            --// While the Leader is here the farm carries on as normal, even
            --// with strangers around; only the Leader leaving starts a follow.
            if IsLeaderInServer() then
                if State.Status ~= "WITH LEADER" then
                    SetStatus("WITH LEADER")
                end

                return
            end

            if now < State.CooldownUntil then
                return
            end

            State.Busy = true
            task.spawn(RunFollow)
        end

        ------------------------------------------------------------------------
        --// UI (Party tab)
        ------------------------------------------------------------------------
        local Section = UIRef.PartySection
        local LeaderOptions = {}

        local function RefreshLeaderLabel()
            local Leader = GetLeader()

            if UIRef.PartyLeaderLabel then
                UIRef.PartyLeaderLabel:Set("LEADER:  " .. (Leader and Leader.Name or "NONE"))
            end
        end

        local function SetLeader(OtherPlayer)
            if OtherPlayer then
                CONFIG.PARTY_LEADER = { Name = OtherPlayer.Name, UserId = OtherPlayer.UserId }
                NotifyAction("Party", "Leader set to " .. OtherPlayer.Name)
            else
                CONFIG.PARTY_LEADER = {}
                NotifyAction("Party", "Leader cleared")
            end

            State.CooldownUntil = 0
            RefreshLeaderLabel()
            AICProfile.SaveActiveProfile()
        end

        function AICUI.RefreshPartyLeaderDropdown()
            table.clear(LeaderOptions)

            local Options = {}

            for _, OtherPlayer in ipairs(Players:GetPlayers()) do
                if OtherPlayer ~= Player then
                    local Label = string.format("%s (@%s)", OtherPlayer.DisplayName, OtherPlayer.Name)
                    LeaderOptions[Label] = OtherPlayer
                    table.insert(Options, Label)
                end
            end

            table.sort(Options, function(A, B)
                return string.lower(A) < string.lower(B)
            end)

            if #Options == 0 then
                Options = { "No other players" }
            end

            UIRef.PartyLeaderDropdown = AICUI.ReplaceDropdown(UIRef.PartyLeaderDropdown, Section, "Set Leader", Options, function(Value)
                local OtherPlayer = LeaderOptions[Value]

                --// Only someone still in this server can be picked.
                if OtherPlayer and OtherPlayer.Parent == Players then
                    SetLeader(OtherPlayer)
                end
            end)
        end

        --// Called after a profile loads, since the Leader is saved per profile.
        function AICUI.RefreshPartyUI()
            RefreshLeaderLabel()
        end

        if Section then
            FeatureState.PartySystem.Button = Section:AddToggle{
                Name = "Party System",
                Default = FeatureState.PartySystem.Enabled,
                Callback = function(Value)
                    FeatureState.PartySystem.Enabled = Value
                    State.CooldownUntil = 0
                    AICProfile.SaveActiveProfile()
                end,
            }

            UIRef.PartyLeaderLabel = Section:AddLabel("LEADER:  NONE")
            UIRef.PartyStatusLabel = Section:AddLabel("STATUS:  IDLE")

            Section:AddButton{
                Name = "Clear Leader",
                Callback = function()
                    SetLeader(nil)
                end,
            }

            Section:AddButton{
                Name = "Refresh Player List",
                Callback = function()
                    AICUI.RefreshPartyLeaderDropdown()
                end,
            }

            AICUI.RefreshPartyLeaderDropdown()
            RefreshLeaderLabel()

            Context.Connect(Players.PlayerAdded, function()
                AICUI.RefreshPartyLeaderDropdown()
            end)

            Context.Connect(Players.PlayerRemoving, function()
                task.defer(AICUI.RefreshPartyLeaderDropdown)
            end)
        end

        return Feature
    end,
}
]======],
}
